const merge = $('Fetch Merge Request').first().json;
const mergeRow = Array.isArray(merge) ? merge[0] : merge;

const itemsInput = $('Fetch Items').all();
let items;
if (itemsInput.length === 1 && Array.isArray(itemsInput[0].json)) {
  items = itemsInput[0].json;
} else {
  items = itemsInput.map(function(i) { return i.json; });
}

// New-parent mode never inserts the anchor listing into
// merge_request_items - it's tracked separately on merge_requests
// (anchor_sku / anchor_own_values), since it was never "added" the way
// the other children were, the same reasoning wf27's Build Payload
// already uses. Without this, the anchor is silently absent from this
// preview: a 2-listing new-parent merge would render only a single
// cell, which reads exactly like that one value belongs to the parent
// itself rather than to the one visible child - it doesn't; the parent
// never carries the dimension attribute at all (confirmed separately in
// wf27's Build Payload, which explicitly skips it). This just makes the
// preview show every real family member, anchor included.
if (mergeRow.is_new_parent && mergeRow.anchor_sku) {
  const anchorOwnValues = mergeRow.anchor_own_values || {};
  items = items.concat([{
    sku: mergeRow.anchor_sku,
    dimension1_value: anchorOwnValues[mergeRow.dimension1_attribute] || null,
    dimension2_value: mergeRow.dimension2_attribute ? (anchorOwnValues[mergeRow.dimension2_attribute] || null) : null
  }]);
}

const isMatrix = !!mergeRow.dimension2_theme;
const dim1Values = [...new Set(items.map(i => i.dimension1_value).filter(Boolean))].sort();
const dim2Values = isMatrix
  ? [...new Set(items.map(i => i.dimension2_value).filter(Boolean))].sort()
  : [];

const cells = [];
const duplicates = [];
const missing = [];

if (isMatrix) {
  for (const d1 of dim1Values) {
    for (const d2 of dim2Values) {
      const matches = items.filter(i => i.dimension1_value === d1 && i.dimension2_value === d2);
      if (matches.length === 0) {
        missing.push({ dimension1_value: d1, dimension2_value: d2 });
        cells.push({ dimension1_value: d1, dimension2_value: d2, sku: null, status: 'missing' });
      } else if (matches.length === 1) {
        cells.push({ dimension1_value: d1, dimension2_value: d2, sku: matches[0].sku, status: 'filled' });
      } else {
        duplicates.push({ dimension1_value: d1, dimension2_value: d2, skus: matches.map(m => m.sku) });
        cells.push({ dimension1_value: d1, dimension2_value: d2, sku: matches[0].sku, status: 'duplicate', all_skus: matches.map(m => m.sku) });
      }
    }
  }
} else {
  for (const d1 of dim1Values) {
    const matches = items.filter(i => i.dimension1_value === d1);
    if (matches.length === 1) {
      cells.push({ dimension1_value: d1, sku: matches[0].sku, status: 'filled' });
    } else if (matches.length > 1) {
      duplicates.push({ dimension1_value: d1, skus: matches.map(m => m.sku) });
      cells.push({ dimension1_value: d1, sku: matches[0].sku, status: 'duplicate', all_skus: matches.map(m => m.sku) });
    }
  }
}

return [{ json: {
  request_id: mergeRow.request_id,
  seller_id: mergeRow.seller_id,
  dimension1_values: dim1Values,
  dimension2_values: dim2Values,
  cells: cells,
  duplicate_combinations: duplicates,
  missing_combinations: missing,
  matrix_confirmed: false
}}];
